const timeInfo = await Aboutme.system.getCurrentTime();
const today = `${timeInfo.year}-${String(timeInfo.month).padStart(2, '0')}-${String(timeInfo.day).padStart(2, '0')}`;
const entries = await Aboutme.plugins.calendar_album.getEntriesForDate({ dateStr: today });
setResult(`今天有 ${entries.length} 条图文`);

const entry = await Aboutme.plugins.calendar_album.addEntry({
  title: '美好的一天',
  content: '今天天气很好，心情愉快！'
});
setResult(`图文已创建: ${entry.id}`);

const timeInfo = await Aboutme.system.getCurrentTime();
const today = `${timeInfo.year}-${String(timeInfo.month).padStart(2, '0')}-${String(timeInfo.day).padStart(2, '0')}`;
const entry = await Aboutme.plugins.calendar_album.addEntry({
  title: '生日聚会',
  content: '今天过生日，很开心！',
  dateStr: today,
  tags: ['生活', '生日'],
  location: '家',
  mood: '😊',
  weather: '晴天',
  imageUrls: ['photos/1.jpg', 'photos/2.jpg']
});
setResult('已添加生日图文');

const updated = await Aboutme.plugins.calendar_album.updateEntry({
  entryId: 'entry123',
  content: '更新后的内容...'
});
setResult('图文已更新');

const entry = await Aboutme.plugins.calendar_album.getEntryById({ entryId: 'entry123' });
if (entry.error) {
  setResult('图文不存在');
} else {
  setResult(JSON.stringify(entry, null, 2));
}

const startDate = await Aboutme.system.getCustomDate({relativePosition: 'startOfMonth', format: 'yyyy-MM-dd'});
const endDate = await Aboutme.system.getCustomDate({relativePosition: 'endOfMonth', format: 'yyyy-MM-dd'});
const photos = await Aboutme.plugins.calendar_album.getPhotosByDateRange({ startDate, endDate });
setResult(JSON.stringify(photos, null, 2));

const entry = await Aboutme.plugins.calendar_album.findEntryBy({field: 'id', value: 'entry123'});
if (entry) {
  setResult(`找到图文: ${entry.title}`);
} else {
  setResult('未找到该图文');
}

const entry = await Aboutme.plugins.calendar_album.findEntryById({id: 'entry123'});
if (entry) {
  setResult(`图文标题: ${entry.title}, 内容: ${entry.content.substring(0, 50)}...`);
} else {
  setResult('图文不存在');
}
